#include <iostream>

long long power(int base, int exp) {
    if (exp == 0) return 1;                // базовый случай
    return base * power(base, exp - 1);    // шаг: exp уменьшается
}

long long powerLoop(int base, int exp) {
    long long result = 1;
    for (int i = 0; i < exp; i++) result *= base;
    return result;
}

int sumDigits(int n) {
    if (n == 0) return 0;                  // базовый случай
    return n % 10 + sumDigits(n / 10);     // шаг: на одну цифру меньше
}

void countDown(int n) {
    if (n == 0) {                          // базовый случай
        std::cout << "Старт!\n";
        return;
    }
    std::cout << n << " ";
    countDown(n - 1);                      // шаг
}

int main() {
    std::cout << power(2, 10) << " " << powerLoop(2, 10) << "\n";  // 1024 1024
    std::cout << power(3, 5) << " " << powerLoop(3, 5) << "\n";    // 243 243
    std::cout << power(7, 0) << " " << powerLoop(7, 0) << "\n";    // 1 1
    std::cout << sumDigits(4827) << "\n";                           // 21
