        if (x < 0 || x > 100) {
            std::cout << "Пропущено: " << x << "\n";
            continue;
        }
        grades.push_back(x);
    }
    if (grades.empty()) {
        std::cout << "Оценок нет\n";
        return 0;
    }

    int sum = 0, best = grades[0], worst = grades[0];
    for (size_t i = 0; i < grades.size(); i++) {
        std::cout << i + 1 << ") " << grades[i] << "\n";
        sum += grades[i];
        if (grades[i] > best) best = grades[i];
        if (grades[i] < worst) worst = grades[i];
    }
    double average = static_cast<double>(sum) / grades.size();
    int above = 0;
    for (int g : grades) if (g > average) above++;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Среднее: " << average << ", макс: " << best << ", мин: " << worst << "\n";
    std::cout << "Выше среднего: " << above << "\n";
}

