std::string maskPhone(const std::string& phone) {
    int digits = 0;
    for (char c : phone) if (c >= '0' && c <= '9') digits++;
    std::string result = phone;
    int toHide = digits - 4;
    for (char& c : result) {
        if (toHide > 0 && c >= '0' && c <= '9') {
            c = '*';
            toHide--;
        }
    }
    return result;
}

