std::string passwordProblem(const std::string& p) {
    if (p.size() < 8) return "короче 8 символов";
    bool upper = false, lower = false, digit = false;
    for (char ch : p) {
        unsigned char c = static_cast<unsigned char>(ch);
        if (std::isspace(c)) return "есть пробел";
        if (std::isupper(c)) upper = true;
        if (std::islower(c)) lower = true;
        if (std::isdigit(c)) digit = true;
    }
    if (!upper) return "нет заглавной буквы";
    if (!lower) return "нет строчной буквы";
    if (!digit) return "нет цифры";
    return "";
}

bool isStrongPassword(const std::string& p) {
    return passwordProblem(p).empty();
}

int digitSum(const std::string& s) {
    int sum = 0;
    for (char c : s) if (c >= '0' && c <= '9') sum += c - '0';
    return sum;
}

