#include <algorithm>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

class Expense {
public:
    Expense(const std::string& category, double amount) : category(category), amount(amount) {
        if (category.empty()) throw std::invalid_argument("пустая категория");
        if (amount <= 0) throw std::invalid_argument("сумма должна быть больше 0");
    }
    const std::string& getCategory() const { return category; }
    double getAmount() const { return amount; }
private:
    std::string category;
    double amount;
};

class ExpenseBook {
public:
    void add(const Expense& e) { items.push_back(e); }
    const std::vector<Expense>& all() const { return items; }

    std::map<std::string, double> totalsByCategory() const {
        std::map<std::string, double> totals;
        for (const Expense& e : items) totals[e.getCategory()] += e.getAmount();
        return totals;
    }

    std::vector<Expense> top(int n) const {
        std::vector<Expense> sorted = items;
        std::sort(sorted.begin(), sorted.end(), [](const Expense& a, const Expense& b) { return a.getAmount() > b.getAmount(); });
        if (static_cast<int>(sorted.size()) > n) sorted.erase(sorted.begin() + n, sorted.end());
        return sorted;
    }

    int removeBelow(double limit) {
        auto before = items.size();
        items.erase(std::remove_if(items.begin(), items.end(), [limit](const Expense& e) { return e.getAmount() < limit; }), items.end());
        return static_cast<int>(before - items.size());
    }

    void load(const std::string& file) {
        std::ifstream in(file);
        std::string category;
        double amount = 0;
        while (in >> category >> amount) {
            try { items.emplace_back(category, amount); } catch (const std::invalid_argument&) {}
        }
    }

    bool save(const std::string& file) const {
        std::ofstream out(file);
        if (!out) return false;
        for (const Expense& e : items) out << e.getCategory() << " " << e.getAmount() << "\n";
        return true;
    }

private:
    std::vector<Expense> items;
};

void printExpenses(const std::vector<Expense>& list) {
    if (list.empty()) std::cout << "Пусто\n";
    for (const Expense& e : list) std::cout << e.getCategory() << "\t" << e.getAmount() << "\n";
}

int main() {
    const std::string file = "expenses.txt";
    ExpenseBook book;
    book.load(file);
    std::cout << std::fixed << std::setprecision(2);

    int choice = -1;
    while (choice != 0) {
        std::cout << "\n1 добавить, 2 все, 3 по категориям, 4 топ-3, 5 удалить меньше, 0 выход: ";
        if (!(std::cin >> choice)) {
            std::cin.clear();
            std::cin.ignore(10000, '\n');
            std::cout << "Введите номер пункта\n";
            choice = -1;   // при ошибке cin записывает 0 — иначе меню закроется
            continue;
        }
        if (choice == 1) {
            std::string category;
            double amount = 0;
            std::cout << "Категория и сумма: ";
            if (!(std::cin >> category >> amount)) {
                std::cin.clear();
                std::cin.ignore(10000, '\n');
                std::cout << "Неверный ввод\n";
                continue;
            }
            try {
                book.add(Expense(category, amount));
            } catch (const std::invalid_argument& e) {
                std::cout << "Ошибка: " << e.what() << "\n";
            }
        } else if (choice == 2) {
            printExpenses(book.all());
        } else if (choice == 3) {
            for (const auto& [category, total] : book.totalsByCategory()) std::cout << category << ": " << total << "\n";
        } else if (choice == 4) {
            printExpenses(book.top(3));
        } else if (choice == 5) {
            double limit = 0;
            std::cout << "Удалить меньше: ";
            if (std::cin >> limit) std::cout << "Удалено: " << book.removeBelow(limit) << "\n";
        }
    }
    std::cout << (book.save(file) ? "Сохранено\n" : "Не удалось сохранить\n");
}

// 1 еда 45.5 / 1 такси 20 / 1 еда 30 / 1 связь -5 → Ошибка: сумма должна быть больше 0
// 3 → еда: 75.50, такси: 20.00
// 4 → еда 45.50, еда 30.00, такси 20.00
// abc → Введите номер пункта
// 0 → Сохранено

